// Normalize an incoming EDR/SIEM alert into a common schema.
// Handles CrowdStrike Falcon-style detections and generic JSON alerts.
const body = $input.first().json.body ?? $input.first().json;

const pick = (...paths) => {
  for (const p of paths) {
    const v = p.split('.').reduce((o, k) => (o == null ? undefined : o[k]), body);
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return null;
};

// Redact obvious secrets BEFORE anything is sent to third-party APIs
const redact = (s) => s
  .replace(/(password|passwd|pwd|secret|token|api[_-]?key)(\\?"?\s*[=:]\s*\\?"?)[^\s"\\,}]+/gi, '$1$2[REDACTED]')
  .replace(/AKIA[0-9A-Z]{16}/g, '[REDACTED_AWS_KEY]');

const rawText = redact(JSON.stringify(body));
const uniq = (a) => [...new Set(a)];

const ips = uniq((rawText.match(/\b(?:\d{1,3}\.){3}\d{1,3}\b/g) || [])
  .filter(ip => !/^(10\.|127\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|0\.|169\.254\.)/.test(ip)));
const sha256 = uniq(rawText.match(/\b[a-fA-F0-9]{64}\b/g) || []);
const domains = uniq((rawText.match(/\b(?:[a-z0-9-]+\.)+(?:com|net|org|io|ru|cn|xyz|top|info|biz|co|me|app|dev|site|online)\b/gi) || [])
  .map(d => d.toLowerCase()));

return [{ json: {
  alert_id: pick('detection_id', 'composite_id', 'id', 'alert_id') ?? `alert-${Date.now()}`,
  source: pick('source', 'product') ?? 'edr',
  received_at: new Date().toISOString(),
  title: pick('name', 'title', 'display_name', 'description') ?? 'Untitled alert',
  severity: pick('severity', 'max_severity_displayname', 'priority') ?? 'unknown',
  hostname: pick('device.hostname', 'hostname', 'host'),
  user: pick('user_name', 'user', 'username'),
  tactic: pick('tactic', 'behaviors.0.tactic'),
  technique: pick('technique_id', 'technique', 'behaviors.0.technique_id'),
  command_line: pick('cmdline', 'command_line', 'behaviors.0.cmdline'),
  parent_process: pick('parent_process', 'behaviors.0.parent_process'),
  iocs: { ips, sha256, domains },
  raw: JSON.parse(rawText),
}}];

// Merge enrichment results and build the Claude triage request.
const alert = $('Normalize Alert').first().json;
const vt = $('VirusTotal Hash Lookup').first().json;
const abuse = $('AbuseIPDB IP Lookup').first().json;

const vtAttr = vt?.data?.attributes;
const enrichment = {
  virustotal: vtAttr?.last_analysis_stats ? {
    hash: alert.iocs.sha256[0],
    malicious: vtAttr.last_analysis_stats.malicious,
    suspicious: vtAttr.last_analysis_stats.suspicious,
    harmless: vtAttr.last_analysis_stats.harmless,
    names: (vtAttr.names || []).slice(0, 5),
    threat_label: vtAttr.popular_threat_classification?.suggested_threat_label ?? null,
  } : { status: alert.iocs.sha256.length ? 'not_found_or_error' : 'no_hash_in_alert' },
  abuseipdb: abuse?.data ? {
    ip: abuse.data.ipAddress,
    abuse_confidence: abuse.data.abuseConfidenceScore,
    country: abuse.data.countryCode,
    isp: abuse.data.isp,
    is_tor: abuse.data.isTor,
    total_reports: abuse.data.totalReports,
  } : { status: alert.iocs.ips.length ? 'not_found_or_error' : 'no_public_ip_in_alert' },
};

const system = `You are a senior incident responder on an internal CSIRT. Triage the alert using ONLY the evidence provided.
Respond with ONLY a JSON object (no markdown, no prose) with exactly these keys:
{
  "verdict": "true_positive" | "benign_true_positive" | "false_positive" | "needs_review",
  "confidence": <integer 0-100>,
  "severity": "critical" | "high" | "medium" | "low",
  "summary": "<2-3 sentence plain-language summary for a responder>",
  "attack_mapping": [{"tactic": "", "technique_id": "", "technique_name": ""}],
  "key_evidence": ["<specific observation from the data>"],
  "recommended_actions": ["<investigative or containment step>"],
  "tuning_suggestion": "<for false/benign positives: a concrete exclusion or logic change; otherwise null>"
}
Rules:
- If enrichment is missing or evidence is ambiguous, use "needs_review".
- Do not invent facts not present in the alert or enrichment.
- Containment actions are recommendations only; an analyst approves them.`;

return [{ json: {
  alert,
  enrichment,
  claude_request: {
    model: 'claude-sonnet-5',
    max_tokens: 1500,
    system,
    messages: [{ role: 'user', content:
      `Triage this alert.\n\nALERT:\n${JSON.stringify(alert, null, 2)}\n\nENRICHMENT:\n${JSON.stringify(enrichment, null, 2)}` }],
  },
}}];

// Parse Claude's verdict with a safe fallback and a confidence guardrail.
const ctx = $('Build Triage Context').first().json;
const resp = $input.first().json;
let t;
try {
  const text = (resp.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
  t = JSON.parse(text.replace(/```json|```/g, '').trim());
} catch (e) {
  t = {
    verdict: 'needs_review', confidence: 0,
    severity: String(ctx.alert.severity || 'medium').toLowerCase(),
    summary: 'Automated triage did not return a parseable verdict; manual review required.',
    attack_mapping: [], key_evidence: [], recommended_actions: ['Manually triage this alert'],
    tuning_suggestion: null, error: resp.error?.message || String(e.message || e),
  };
}

// Guardrail: anything under 70% confidence goes to a human
const THRESHOLD = 70;
if (t.verdict !== 'needs_review' && (t.confidence ?? 0) < THRESHOLD) {
  t.original_verdict = t.verdict;
  t.verdict = 'needs_review';
}

return [{ json: { ...ctx.alert, enrichment: ctx.enrichment, triage: t, verdict: t.verdict } }];

// Pre-render the case payload and Slack messages for each route.
const a = $input.first().json;
const t = a.triage;
const techniques = (t.attack_mapping || []).filter(m => m.technique_id)
  .map(m => `${m.technique_id} ${m.technique_name || ''}`.trim());
const bullets = (arr) => (arr || []).map(x => `• ${x}`).join('\n') || '• none';
const header = `*${a.title}*\nHost: \`${a.hostname ?? 'n/a'}\` | User: \`${a.user ?? 'n/a'}\` | Alert: \`${a.alert_id}\``;

const vt = a.enrichment.virustotal, ab = a.enrichment.abuseipdb;
const enrichLine = [
  vt.malicious !== undefined ? `VT: ${vt.malicious} malicious${vt.threat_label ? ` (${vt.threat_label})` : ''}` : null,
  ab.abuse_confidence !== undefined ? `AbuseIPDB: ${ab.ip} score ${ab.abuse_confidence}${ab.is_tor ? ' (Tor exit)' : ''}` : null,
].filter(Boolean).join(' | ') || 'No external enrichment hits';

const jiraList = (arr) => (arr || []).map(x => `* ${x}`).join('\n') || 'n/a';

return [{ json: { ...a,
  jira_payload: { fields: {
    project: { key: 'CSIRT' },
    issuetype: { name: 'Task' },
    summary: `[${String(t.severity || 'medium').toUpperCase()}] ${a.title} on ${a.hostname ?? 'unknown host'}`.slice(0, 250),
    labels: ['auto-triage', ...techniques.map(x => x.split(' ')[0].replace(/\./g, '_'))],
    description: [
      `h3. Summary\n${t.summary}`,
      `h3. MITRE ATT&CK\n${jiraList(techniques)}`,
      `h3. Key evidence\n${jiraList(t.key_evidence)}`,
      `h3. Recommended actions (analyst approval required)\n${jiraList(t.recommended_actions)}`,
      `h3. Enrichment\n${enrichLine}`,
      `h3. Triage metadata\nVerdict: ${t.verdict} | Confidence: ${t.confidence}% | Model: claude-sonnet-5`,
      `h3. Raw alert (redacted)\n{code:json}${JSON.stringify(a.raw, null, 2).slice(0, 20000)}{code}`,
    ].join('\n\n'),
  }},
  slack_incident: `:rotating_light: *Likely true positive* (${t.confidence}% confidence, ${t.severity})\n${header}\n\n${t.summary}\n\n*ATT&CK:* ${techniques.join(', ') || 'n/a'}\n*Enrichment:* ${enrichLine}\n*Recommended (needs approval):*\n${bullets(t.recommended_actions)}`,
  slack_tuning: `:broom: *${a.verdict.replace(/_/g, ' ')}*, not escalated (${t.confidence}% confidence)\n${header}\n\n${t.summary}\n*Tuning suggestion:* ${t.tuning_suggestion || 'none provided'}`,
  slack_review: `:mag: *Needs analyst review*${t.original_verdict ? ` (model leaned ${t.original_verdict} at ${t.confidence}%)` : ''}\n${header}\n\n${t.summary}\n*Evidence:*\n${bullets(t.key_evidence)}\n*Enrichment:* ${enrichLine}`,
}}];
